  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Inferir sem abandonar as pistas do texto', 'Inferir é ligar pistas a uma conclusão que não está escrita literalmente. Uma inferência forte pode ser justificada por trechos e reconhece o que continua desconhecido. Plausível não significa confirmado.', '## Dado, pista e inferência
Uma informação explícita está diretamente no texto: “a janela estava aberta”. Uma inferência conecta essa pista a outra informação para propor uma leitura: “pode ter entrado vento”. A segunda frase não é um fato explícito e ainda pode haver outras explicações.

## Mostre o caminho
Volte ao trecho, destaque a pista e explique como ela apoia a conclusão. Em narrativas, uma fala, uma ação e a reação de outro personagem podem se combinar. Em avisos e notícias, observe quem é citado, qual período foi medido e a que situação a informação se aplica.

## Calibre a certeza
Use “sugere”, “é provável” ou “pode indicar” quando as pistas permitem uma hipótese, mas não a confirmam. Evite transformar ausência de informação em prova: uma página em branco não prova que alguém não sabe; um horário não informado não pode ser inventado.

## Compare alternativas
Uma resposta pode parecer possível pela experiência pessoal, mas não ser a mais apoiada pelo texto. Pergunte: qual trecho sustenta esta opção? Que dado adicional seria necessário para as outras? Quando duas leituras continuam possíveis, registre a ambiguidade em vez de forçar uma certeza.

## Exemplo resolvido
“Quando o ônibus chegou, Lina guardou o guarda-chuva ainda pingando e conferiu o relógio. ‘A apresentação já começou?’, perguntou.” As pistas sugerem preocupação em ter perdido parte do evento. Não sabemos por que o ônibus chegou naquele horário, se a apresentação começou nem se Lina perdeu alguma parte. A resposta cuidadosa mostra tanto a pista quanto o limite.',
    'Trecho: “A sala estava silenciosa. Sobre a mesa, havia três folhas preenchidas e uma quarta em branco. Júlia conferiu o relógio e chamou a colega.” Pistas: o silêncio, as folhas e a quarta página em branco; ação: conferir o relógio e chamar alguém. Inferência possível: a atividade talvez estivesse perto do fim ou Júlia buscasse ajuda. O trecho não confirma nenhuma dessas leituras nem diz por que a folha ficou vazia. Uma resposta adequada explicita a hipótese e cita o que ainda não sabemos.', array['Cite uma palavra, ação ou dado específico como pista.', 'Explique a ligação entre a pista e a conclusão.', 'Prefira uma conclusão limitada quando houver várias causas possíveis.', 'Não transforme uma informação ausente em resposta certa.', 'Se duas leituras forem compatíveis, explique a ambiguidade.']::text[], 22, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"portuguese-infer-from-clues","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Localizar informações explícitas.","Reconhecer ações, falas e relações simples no texto.","Distinguir dado observado de explicação proposta."],"key_concepts":["informação explícita","pista textual","inferência","justificativa","grau de certeza","ambiguidade","limite da evidência"],"progression":[{"stage":"FOUNDATION","focus":"Localizar pistas e distinguir informação explícita de inferência.","questionIds":["v5-pt-infer-probe-01","v5-pt-infer-probe-02","v5-pt-infer-probe-03","v5-pt-infer-practice-01","v5-pt-infer-practice-02","v5-pt-infer-practice-03","v5-pt-infer-practice-04"]},{"stage":"APPLICATION","focus":"Combinar pistas, comparar alternativas e calibrar a certeza.","questionIds":["v5-pt-infer-practice-05","v5-pt-infer-practice-06","v5-pt-infer-practice-07","v5-pt-infer-practice-08","v5-pt-infer-practice-09","v5-pt-infer-practice-10","v5-pt-infer-practice-11"]},{"stage":"TRANSFER","focus":"Usar pistas em gêneros diversos e explicitar explicações alternativas.","questionIds":["v5-pt-infer-transfer-01","v5-pt-infer-transfer-02","v5-pt-infer-transfer-03","v5-pt-infer-transfer-04","v5-pt-infer-transfer-05","v5-pt-infer-transfer-06","v5-pt-infer-transfer-07"]},{"stage":"INTEGRATION","focus":"Justificar interpretações e reconhecer limites do que se pode concluir.","questionIds":["v5-pt-infer-lock-01","v5-pt-infer-lock-02","v5-pt-infer-lock-03","v5-pt-infer-lock-04","v5-pt-infer-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar distinções entre fato, inferência e hipótese em contextos novos.","questionIds":["v5-pt-infer-review-01","v5-pt-infer-review-02","v5-pt-infer-review-03","v5-pt-infer-review-04","v5-pt-infer-review-05","v5-pt-infer-review-06","v5-pt-infer-review-07","v5-pt-infer-review-08","v5-pt-infer-review-09"]}],"micro_explanations":[{"trigger":"QUOTE_THE_CLUE","text":"Aponte o trecho que sustenta sua leitura. Sem pista, a resposta pode ser apenas uma suposição."},{"trigger":"PLAUSIBLE_NOT_CONFIRMED","text":"Uma hipótese pode fazer sentido e ainda não estar confirmada. Diga o que a pista sugere e o que falta saber."},{"trigger":"EXPLICIT_VS_INFERRED","text":"O texto informa diretamente uma coisa; você pode inferir outra ao relacionar pistas. Marque essa diferença."},{"trigger":"LIMIT_THE_SCOPE","text":"Delimite a conclusão ao personagem, período, amostra ou local que o texto apresenta."},{"trigger":"ALTERNATIVE_EXPLANATION","text":"Se outra explicação também combina com a pista, não afirme uma causa única sem evidência."},{"trigger":"AMBIGUOUS_TEXT","text":"Quando o texto não resolve a dúvida, reconhecer a ambiguidade também é uma leitura fundamentada."}],"remediations":[{"id":"TEXTUAL_CLUE","misconception":"TEXTUAL_CLUE","prompt":"Volte ao trecho, marque uma ou duas pistas e complete: “Isso sugere ___ porque ___”."},{"id":"LIMIT_INFERENCE","misconception":"LIMIT_INFERENCE","prompt":"Risque detalhes que não aparecem nem decorrem das pistas. Reescreva a conclusão usando “pode” ou “sugere” quando necessário."},{"id":"EXPLICIT_OR_INFERRED","misconception":"EXPLICIT_OR_INFERRED","prompt":"Separe em duas colunas: o que o texto diz literalmente e o que você conclui a partir disso."},{"id":"COMPARE_ALTERNATIVES","misconception":"COMPARE_ALTERNATIVES","prompt":"Para cada alternativa, aponte a pista que a apoia. Descarte as que exigem fatos ausentes."},{"id":"AMBIGUITY_CHECK","misconception":"AMBIGUITY_CHECK","prompt":"Imagine uma segunda explicação compatível com as mesmas pistas. Se não há como escolher entre elas, registre o limite em vez de adivinhar."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Base Nacional Comum Curricular: Educação Infantil e Ensino Fundamental","publisher":"Ministério da Educação","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","accessedOn":"2026-10-13","supports":["O documento trata de estratégias de leitura, inferências e justificativas apoiadas em pistas textuais em diferentes campos e anos."],"use":"Referência curricular de escopo; não representa aprovação de mapeamento da habilidade interna PORTUGUESE_INFER_FROM_CLUES."},{"title":"Língua Portuguesa: relações lógico-discursivas nos textos","publisher":"Secretaria Municipal de Educação de Goiânia, Conexão Escola","url":"https://sme.goiania.go.gov.br/conexaoescola/ensino_fundamental/lingua-portuguesa-as-relacoes-logico-discursivas-nos-textos/","accessedOn":"2026-10-13","supports":["Material aberto propõe leitura atenta de pistas lexicais e estruturais e justificação de interpretações."],"use":"Referência didática de apoio; enunciados e exemplos do pacote são autorais."}],"copyright_note":"Textos, alternativas, exemplos e atividade são autorais e fictícios. As fontes orientam escopo; mapeamento oficial e revisão pedagógica humana seguem pendentes.","authentic_activities":[{"id":"v5-portuguese-evidence-inference-sort","title":"Pistas, conclusões e perguntas em aberto","objective":"Justificar inferências com pistas textuais e reconhecer quando uma conclusão excede a evidência.","context":"Grupos analisam três microtextos fictícios de gêneros diferentes: narrativa, aviso e notícia curta.","materials":["Cartões com textos fictícios","Quadro com colunas “trecho”, “o que informa”, “o que sugere” e “o que falta saber”","Canetas ou marcadores opcionais"],"instructions":"Cada grupo escolhe um microtexto, sublinha duas pistas e registra uma informação explícita e uma inferência. Em seguida, escreve uma explicação alternativa que também poderia combinar com as pistas e indica qual dado resolveria a dúvida. Trocam os cartões com outro grupo, que tenta localizar o apoio textual. Nenhum relato pessoal é solicitado.","evidence":"Quadro preenchido com pistas citadas, inferência ligada a elas, limite reconhecido e pergunta pertinente para obter evidência adicional.","safety":"Use apenas personagens e situações fictícias; ofereça resposta oral, escrita ou por cartões e não associe interpretações a histórias pessoais dos estudantes.","privacyGuard":"Não coletar nomes, relatos pessoais, desempenho individual público nem dados identificáveis; guardar somente o produto do grupo, se necessário.","ageRange":"6º ao 9º ano do Ensino Fundamental, ajustando extensão e vocabulário dos microtextos.","mediation":"O professor pede que estudantes apontem a pista antes de avaliar a resposta. Quando duas leituras forem apoiadas, reconhece ambas e discute que dado diferenciaria as hipóteses.","rubric":[{"criterion":"Uso de pistas","emerging":"Apresenta uma conclusão sem localizar evidência.","developing":"Localiza uma pista após orientação, mas não explica a ligação.","proficient":"Cita pistas e explica como sustentam a conclusão."},{"criterion":"Calibração da inferência","emerging":"Trata suposição como fato confirmado.","developing":"Usa linguagem cautelosa com mediação.","proficient":"Distingue explicitamente fato, hipótese e informação ainda desconhecida."},{"criterion":"Consideração de alternativas","emerging":"Ignora outras explicações possíveis.","developing":"Reconhece uma alternativa quando questionado.","proficient":"Propõe alternativa compatível e indica que evidência ajudaria a diferenciá-la."}]}],"objective":"Construir inferências justificáveis conectando pistas textuais e conhecimento pertinente, distinguindo o que o texto diz do que o leitor conclui.","common_mistake":"Completar lacunas com a própria experiência, confundir hipótese plausível com fato textual, escolher resposta sem indicar pista, generalizar um caso limitado e ignorar que mais de uma leitura pode permanecer possível.","estimated_minutes":22}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
